sys_script.script:
// B.2 ITF Submission Validation
//
// Business rule script for x_snc_sas_positi_0_case. Loaded via Now.include().
// Legacy (non-module) script using the platform-injected globals.
//
// Runs `before update`, gated by the rule's condition
//   current.request_status.changesTo('awaiting_certification')
// so it only fires on the transition into director certification. changesTo is
// reliable here because this is an update-only rule: `previous` exists, so there
// is a genuine prior value to compare against. (Contrast B.1, which is a derive
// rule that also runs on insert and therefore must not be gated on change
// detection at all.)
//
// Blocks submission unless the org chart is attached, an unbudgeted request
// names its offset position, and the funding splits total exactly 100%.
// Never calls current.update() — this is a before rule.
(function executeRule(current, previous) {
    var errors = [];

    if (current.org_chart.nil()) {
        errors.push(gs.getProperty('x_snc_sas_positi_0.msg_org_chart'));
    }

    if (current.getValue('budget_status') == 'unbudgeted' && current.offset_position_number.nil()) {
        errors.push(gs.getProperty('x_snc_sas_positi_0.msg_offset_position'));
    }

    // Sum the child funding rows ROW BY ROW, deliberately NOT with GlideAggregate.
    //
    // The spec specified GlideAggregate.addAggregate('SUM', 'funding_pct'), but
    // that was MEASURED returning a wrong total on this instance when the splits
    // are uneven. Verified against live fixtures:
    //   ITF0000114  rows 40 + 60  -> row-by-row 100, GlideAggregate SUM  40.00  WRONG
    //   ITF0000116  rows 50 + 50  -> row-by-row 100, GlideAggregate SUM 100.00  ok
    // The equal-rows case passes by coincidence, which is how this hid. Using the
    // aggregate would abort certification on a legitimate 60/40 funded request.
    var total = 0;
    var f = new GlideRecord('x_snc_sas_positi_0_funding');
    f.addQuery('parent_case', current.getUniqueValue());
    f.query();
    while (f.next()) {
        total += parseFloat(f.getValue('funding_pct') || '0');
    }

    // funding_pct is Decimal(5,2), so compare with a tolerance rather than ==.
    if (Math.abs(total - 100) > 0.001) {
        errors.push(gs.getProperty('x_snc_sas_positi_0.msg_funding_total'));
    }

    if (errors.length > 0) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
    }
})(current, previous);
